int invalid_count = 0;
FILE *log_file = fopen("invalid_records.log", "r");
if (log_file != NULL) {
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), log_file) != NULL) {
        invalid_count++;
    }
    fclose(log_file);
}

// ... existing printf statements for the report ...
printf("Summary Report:\n");
// ... other metrics ...
printf("Invalid BP Records: %d\n", invalid_count);
